import{_ as o,o as r,c as e,ag as n}from"./chunks/framework.D5hoimZQ.js";const m=JSON.parse('{"title":"科技爱好者周刊 #413 提炼：再见了 React Native ｜ 世界地图的新投影","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/weekly-413-analysis.md","filePath":"topics/ai-system-architecture/weekly-413-analysis.md"}'),s={name:"topics/ai-system-architecture/weekly-413-analysis.md"};function i(a,t,d,l,g,c){return r(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="科技爱好者周刊-413-提炼-再见了-react-native-世界地图的新投影" tabindex="-1">科技爱好者周刊 #413 提炼：再见了 React Native ｜ 世界地图的新投影 <a class="header-anchor" href="#科技爱好者周刊-413-提炼-再见了-react-native-世界地图的新投影" aria-label="Permalink to &quot;科技爱好者周刊 #413 提炼：再见了 React Native ｜ 世界地图的新投影&quot;">​</a></h1><blockquote><p>来源：阮一峰《科技爱好者周刊》第 413 期（封面：华东师范大学闵行校区新启用的西校门，仿其前身光华大学校门） 原文链接：<a href="https://github.com/ruanyf/weekly/blob/master/docs/issue-413.md" target="_blank" rel="noreferrer">https://github.com/ruanyf/weekly/blob/master/docs/issue-413.md</a> 直链：<a href="https://raw.githubusercontent.com/ruanyf/weekly/master/docs/issue-413.md" target="_blank" rel="noreferrer">https://raw.githubusercontent.com/ruanyf/weekly/master/docs/issue-413.md</a> 抓取校验：2026-09-18 抓取成功，正文 350 行 / 17,731 字节，含标题「科技爱好者周刊（第 413 期）」✅ 外部核实：Shopify 工程博客《Native is now the future of mobile at Shopify》（2026-09-10）+ Not-Ship《The UN challenges five centuries of cartography》（2026-09-09）+ UN News / 新华社关于 Equal Earth 决议的报道 + GitHub API 实测全部工具仓库 状态：已落盘 · 周刊监控第 2 期（上一期 #412） 备注：本期为中秋＋十一假期前的最后一期，周刊将休刊两周。</p></blockquote><hr><h2 id="一、本期主文" tabindex="-1">一、本期主文 <a class="header-anchor" href="#一、本期主文" aria-label="Permalink to &quot;一、本期主文&quot;">​</a></h2><h3 id="_1-再见了-react-native" tabindex="-1">1. 再见了，React Native <a class="header-anchor" href="#_1-再见了-react-native" aria-label="Permalink to &quot;1. 再见了，React Native&quot;">​</a></h3><p><strong>⚠️ 编者注（先说一处周刊笔误）</strong></p><p>周刊正文写「<strong>Spotify</strong> 宣布，放弃 React Native，改用 Swift 和 Kotlin」，但它给出的两个链接都是 <strong><code>shopify.engineering</code></strong>。经 curl 核实原文：这是 <strong>Shopify</strong> 的工程博客文章《Native is now the future of mobile at Shopify》（2026-09-10），副标题是「Coding agents changed what it costs to build mobile apps twice」。Spotify 与 Shopify 名字相近，周刊此处应为笔误。<strong>引用这条新闻时请用 Shopify。</strong></p><p><strong>原文主张（阮一峰）</strong></p><ul><li>Shopify 2020 年高调宣布放弃原生、全面转向 React Native（当时给的三条理由，周刊原文引用：不为每个平台重复开发相同功能／允许开发人员跨技术栈工作／省下的时间精力用来创造更多价值）。</li><li>六年后反转：改回 Swift + Kotlin 原生开发 iOS 和安卓。</li><li>周刊的判断很锋利：「说实话，这三个理由都是场面话，真正的理由只有一个：<strong>省钱</strong>。」——当年省钱所以用 RN（一个团队 vs 两个团队），如今放弃 RN 也是为了省钱，<strong>因为有了 AI，用什么语言根本无所谓</strong>。</li><li>周刊的结论句：「AI 就是一个无所不能的自动翻译器，一旦问世，像 React Native 这种中间语言或者翻译层，就被判死刑了，此刻开始退出历史舞台成了必然的结局。」</li><li>顺带批评 RN：「2015 年发布，迄今超过 10 年，一些基本的技术问题至今没有很好地解决……它被别人替代，一点都不冤。」</li></ul><p><strong>外部核实（原文怎么说的，比周刊更精细）</strong></p><p>Shopify 原文章节标题直译：</p><ul><li>开篇承认 2020 的赌注「极其成功」，并坦承 2025 年 1 月作者自己还写过「RN 的未来是光明的」——“That was true based on what we knew then.”</li><li>转折点：<strong>“Since then, coding models have gotten dramatically better, and for our apps and our team, building the same feature in Swift and Kotlin no longer carries the cost it used to.”</strong></li><li>方法：从第一性原理重估技术栈，用 LLM 先把最大几款 App 的核心部分用 Swift/Kotlin 重做原型，结果“surprisingly well”： <ul><li>Agent 可以<strong>拿 iOS 版本作参考去实现 Android 版本，反之亦然</strong>；</li><li>帮开发者在本职技术栈之外快速上手并有效贡献；</li><li>通过共享规格、测试、评审检查点，把“维持两端功能对齐”的成本大幅压低。</li></ul></li><li><strong>关键的一句自我限定（周刊没提，但很重要）</strong>：“Native still means building and maintaining software on two platforms, that cost has not disappeared. What changed is that agents can now do enough of the implementation, translation, testing, and review work that it’s no longer the deciding factor it was in 2020.”（成本没消失，只是不再是决策中的决定性因素。）</li><li>迁移态度：保留并继续投入 RN 开源库——<strong>React Native Skia 由 Shopify 赞助到 2026 年底</strong>，作者 William Candillon 之后继续维护；希望“clean transition with no surprises”。</li></ul><p><strong>我的评注</strong></p><p>周刊的“AI 万能翻译器 → 中间层判死刑”是一个好记的口号，但<strong>比 Shopify 原文的结论更激进</strong>，有两处要打折：</p><ol><li>Shopify 说的是「<strong>共享实现的价值下降了</strong>，贴近平台能力的价值仍在那里」，而不是「语言随便选」。它明确说跨平台维护成本没消失。</li><li>RN 被替代的直接原因不是“它烂”，而是<strong>它的核心卖点（写一次、跑两端）恰好是 LLM 最擅长替代的那部分</strong>。一个中间层框架的价值，取决于它节省的那部分工作量相对于 AI 后有多值钱——AI 一降价，纯“翻译/对齐”层的经济地基就被抽走了。</li></ol><p>这条新闻真正的结构性含义是：<strong>AI 最先吃掉的是“翻译层”，而不是“能力层”</strong>。任何以“减少重复劳动/格式转换/跨端对齐”为主要价值主张的中间件（跨端框架、低代码胶水、ORM 映射、甚至部分 RPA），都该重新算一遍账。反过来，<strong>离平台/物理/领域最近的那一层，反而更保值</strong>。</p><p>一个反向的自洽性检查：周刊同一期引 Liz Fong-Jones 说“大模型把程序员变成管上下文的人”，又说“用什么语言无所谓”——两者其实同源：当实现的边际成本趋零，<strong>稀缺的从“写”移到“判断写什么、以及判断写得对不对”</strong>。这与 #412 的主线（产出廉价化 → 价值向验证与注意力两端迁移）完全同一条线。</p><p>→ 库内呼应：<code>gear-shaft-org-reinvention.md</code>（砍天轴：别外挂中间层，要推倒重来）、<code>weekly-412-analysis.md</code>（验证成为新瓶颈）、<code>cognitive-atrophy-knowledge.md</code>（当 AI 替你做判断）</p><h3 id="_2-世界地图的新投影方法" tabindex="-1">2. 世界地图的新投影方法 <a class="header-anchor" href="#_2-世界地图的新投影方法" aria-label="Permalink to &quot;2. 世界地图的新投影方法&quot;">​</a></h3><p><strong>原文主张（阮一峰）</strong></p><ul><li>联合国投票决定“废除”墨卡托投影，对各国无约束力，但标志着墨卡托过时。</li><li>平面地图必然失真，必须选一种投影。</li><li>墨卡托＝把地球仪直接拉伸成矩形 → 高纬被极大拉伸。<strong>图中非洲看上去跟格陵兰一样大，实际前者面积是后者的 14 倍</strong>。</li><li>联合国建议采用<strong>平等地球投影法（Equal Earth Projection）</strong>：核心原则是不改变面积比（一块土地占地球 1%，地图上也应占 1%）。</li><li>代价：按面积拉伸 → 形状失真，长宽都可能变形，<strong>不能用于精确导航</strong>。</li><li>附两张对比图（墨卡托 vs 平等地球的欧洲与非洲）。</li></ul><p><strong>外部核实（把转述钉成事实）</strong></p><table tabindex="0"><thead><tr><th>周刊表述</th><th>核实</th><th>更精确的表述</th></tr></thead><tbody><tr><td>联合国投票决定废除墨卡托</td><td>✅ 属实，但<strong>表述偏强</strong></td><td>2026-09-04（周五）联合国大会通过的是<strong>非约束性决议</strong>，鼓励各国政府、学校、媒体采用更准确反映各大洲真实面积的投影（即 Equal Earth），<strong>并未“废除”任何东西</strong>，也不改变边界、领海、任何法律效果</td></tr><tr><td>（周刊未给票数）</td><td>✅</td><td><strong>164 票赞成、1 票反对</strong>（美国），非洲联盟主导推动</td></tr><tr><td>平等地球投影法</td><td>✅</td><td>Equal Earth，<strong>2018 年</strong>由制图学家 Bojan Šavrič、Tom Patterson、Bernhard Jenny 设计，直接回应 <strong>2017 波士顿公立学校改用 Gall-Peters</strong> 引发的制图学争论</td></tr><tr><td>高纬被拉伸，非洲 vs 格陵兰</td><td>✅</td><td>格陵兰在中纬度墨卡托图中常态“看起来与非洲同大”，实际面积约为其 <strong>1/14</strong>；墨卡托 1569 年为航海设计，其核心优势是<strong>等角航线</strong>（图上直线＝恒定罗盘方位）</td></tr><tr><td>不能用于精确导航</td><td>✅</td><td>面积正确的代价是形状/角度失真；<strong>Google Maps 等导航应用几乎不会因此更换投影</strong>（导航要的是方位与局部一致，不是面积）</td></tr></tbody></table><p>决议原文金句（UN 决议本身，Not-Ship 与 UN News 报道一致）：<strong>“Correcting cartographic distortions of continental sizes constitutes an act of cognitive justice and memorial reparation.”</strong>（纠正大陆面积的制图失真，是一项认知正义与纪念性补偿的行为。）</p><p><strong>我的评注</strong></p><p>这条新闻表面是地理，实质是**“表征的政治经济学”**：</p><ol><li><strong>投影即取舍，且不可兼得</strong>。球面到平面<strong>不存在</strong>同时保面积、保形状、保距离、保方向的投影（这是数学事实，不是工程妥协）。所以“选哪种投影”从来不是技术问题，而是<strong>你愿意让哪种失真发生</strong>的价值观声明。墨卡托保方向（航海有用）、代价是放大北方——几百年来它同时充当“导航工具”和“世界观的默认值”，这两重身份被混为一谈。</li><li><strong>默认表征会悄悄变成规范</strong>。人们无意识地把“大小”当作“重要性”的代理 → 面积失真就被读成权力叙事。这与库内布迪厄「惯习/符号权力」和《中国社会各阶级的分析》里“谁的定义在起作用”是同一类问题：<strong>地图是符号权力最便宜、最无处不在的载体</strong>。</li><li><strong>给予知识库的隐喻</strong>：任何知识表征（摘要、向量、知识图谱）都是“有损投影”。选哪种“投影”，取决于你要拿来干什么——就像墨卡托适合导航、Equal Earth 适合面积比较。<strong>没有“正确的知识表示”，只有“为某类问题而选的失真方式”</strong>。这条直接呼应 ASF 里「meaning = attractor，表征即约束」的立场。</li></ol><p>→ 库内呼应：<code>novel-architecture-topological-field.md</code>、<code>tfm-v1-formalization.md</code>（表征与不变量的取舍）、<code>mao-zedong/</code>（谁的定义在起作用）、<code>cross-domain-synthesis-2026-q3.md</code></p><hr><h2 id="二、科技动态" tabindex="-1">二、科技动态 <a class="header-anchor" href="#二、科技动态" aria-label="Permalink to &quot;二、科技动态&quot;">​</a></h2><h3 id="_1-隐藏摄像头检测器-韩国" tabindex="-1">1. 隐藏摄像头检测器（韩国） <a class="header-anchor" href="#_1-隐藏摄像头检测器-韩国" aria-label="Permalink to &quot;1. 隐藏摄像头检测器（韩国）&quot;">​</a></h3><ul><li>形态：一块电路板 + 多个发光二极管 + 手机连接，<strong>造价很低</strong>。</li><li>原理（周刊讲得很清楚，值得记）：LED 发出的光被隐藏摄像头反射回来；难点是<strong>如何在众多反射中排除普通镜面</strong>。巧解是<strong>依次点亮不同位置的 LED</strong>——平面镜反射不产生位置偏移，而摄像头是<strong>凸透镜</strong>，反射光会发生位置偏移；用不同位置的光源即可定位偏移点，从而确定摄像头位置。</li><li>我的评注：这是一个“用<strong>时空编码</strong>换取信噪比”的漂亮工程范式——不靠更贵的传感器，而靠<strong>改变探测序列</strong>把目标从背景里分辨出来。同一种思想在雷达（脉冲编码）、光学（结构光）、乃至 LLM（多次采样投票）里反复出现。</li></ul><h3 id="_2-一句话新闻" tabindex="-1">2. 一句话新闻 <a class="header-anchor" href="#_2-一句话新闻" aria-label="Permalink to &quot;2. 一句话新闻&quot;">​</a></h3><p>（1）<strong>胡塞武装用伪造指挥官音频赢得战果</strong> —— 伪造一段“指挥官命令撤退”的音频，让网红在推特上传播，对方部队真的陷入混乱，己方以小代价占领地盘。</p><ul><li>这是本期<strong>最需要警惕</strong>的一条：AI 合成媒体已从“信息污染”跨到<strong>直接作用于指挥链的实战武器</strong>。它的攻击面不是设备，而是<strong>组织的信任结构</strong>（音频这种“低带宽高信任”的渠道，恰恰最缺验证机制）。</li><li>对照库内：<code>cybersecurity/pentagi-autonomous-pentest.md</code>（攻击自动化）、<code>llm-reasoning-verification-thermodynamic.md</code>（可审计验证的必要性）——<strong>能验证的渠道才可信</strong>，这句话从数学证明一路管到战场音频。</li></ul><p>（2）<strong>笔记本进入固态散热时代</strong> —— 不再需要风扇，靠石墨烯/铜箔贴片散热，机器可以极薄极轻。联想 ThinkBook AeroBlade 14 概念机 <strong>830 克</strong>，华为 14 寸 MateBook Pro S <strong>798 克</strong>。</p><ul><li>关联 <code>topics/materials/2026-q3-breakthroughs.md</code>（石墨烯材料线：本期材料的另一处落点是石墨烯缺陷界面的水裂解）。</li><li>判断：无风扇化的真正瓶颈不是散热片，而是<strong>热量能不能横向铺得开</strong>（热点扩散 &gt; 总量排出）。这条与风电/电力电子的功率密度问题同构。</li></ul><p>（3）<strong>成都“词元券”＋“词元贷”</strong> —— 企事业单位可免费申领，Token 消费政府补贴不超过 30%；还计划允许向银行贷款消费 Token。</p><ul><li>这是**“Token 准公用事业化”<strong>的强信号：算力/Token 开始被当作水电一类</strong>可补贴、可定向、可加杠杆的生产要素**。</li><li>值得记的机制细节：补贴按<strong>消费金额比例</strong>而非配额发放，等于政府直接给“使用量”定价打折 → 会天然偏向高频重度用户。</li><li>关联 <code>llm-cache-pricing.md</code>（Token 定价与缓存 50 倍差价）、<code>ai-industry-2026-q3-knowledge.md</code>（国产化路径、市场分化）。</li></ul><hr><h2 id="三、文章" tabindex="-1">三、文章 <a class="header-anchor" href="#三、文章" aria-label="Permalink to &quot;三、文章&quot;">​</a></h2><ol><li><strong>我的 HTML 模板文件</strong>（vale.rocks）—— 2026 年的网页 HTML boilerplate 应长什么样，逐行解释作用。适合做前端基线模板参考。</li><li><strong>如何用 JavaScript 取消 CSS</strong>（css-tricks）—— 初级教程，用 JS 去掉网页样式表。实用小技巧（阅读模式、截图前清理）。</li><li><strong>容器管理工具和反向代理工具</strong>（kiranet，经 Wayback 存档）—— 作者讲自己<strong>自托管服务器的技术栈与工具选型</strong>。→ <strong>与用户自托管栈直接相关</strong>（对位库内自托管经验）。</li><li><strong>JavaScript 的怪异之处</strong>（stack-auth）—— JS 冷门语法坑科普。</li><li><strong>谷歌搜索的 udm 参数</strong>（serpapi）—— URL 加 <code>udm</code> 参数可直取特定类型结果，如 <code>udm=2</code> 返回图像结果。→ <strong>可直接入外脑检索工具箱</strong>：做无 JS 的信息源抓取时，<code>udm</code> 比在页面上点标签更稳。</li><li><strong>熵的解释</strong>（engineersedge）—— 通俗长文讲“熵”，配大量插图。“熵”在本库是一条贯穿线：热力学 → 信息论 → LLM 温度/交叉熵 → 压缩即理解（<code>llm-scaling-limits.md</code>、<code>llm-reasoning-verification-thermodynamic.md</code>），这条可作为入门材料的备选。</li></ol><hr><h2 id="四、工具-含-github-实测与接入评估" tabindex="-1">四、工具（含 GitHub 实测与接入评估） <a class="header-anchor" href="#四、工具-含-github-实测与接入评估" aria-label="Permalink to &quot;四、工具（含 GitHub 实测与接入评估）&quot;">​</a></h2><p>全部用 GitHub API 实测（2026-09-18），星数/许可证/活跃度以实测为准：</p><table tabindex="0"><thead><tr><th>工具</th><th>实测数据</th><th>一句话</th><th>接入用户工作流的价值</th></tr></thead><tbody><tr><td><a href="https://github.com/posit-dev/great-tables" target="_blank" rel="noreferrer">Great Tables</a></td><td>Python · <strong>2752★</strong> · MIT · 2026-09-14 仍活跃 · 建 2022</td><td>Python 生成“可发布级”复杂表格（Posit 出品）</td><td>⭐ <strong>高</strong>。风电/PyPSA 仿真结果、周报、知识库统计的直接出表工具，比手搓 markdown 表稳</td></tr><tr><td><a href="https://github.com/cryptpad/cryptpad" target="_blank" rel="noreferrer">CryptPad</a></td><td>JS · <strong>7923★</strong> · <strong>AGPL-3.0</strong> · 2026-09-17 活跃 · 建 2014</td><td>端到端加密的在线 Office 套件，可自托管</td><td>⭐ <strong>高（自托管线）</strong>。Docker 自托管可替代飞书文档/Google Docs 的“私密草稿”场景。<strong>⚠️ AGPL-3.0 强传染：改代码提供网络服务须开源全部改动</strong>——自托管合规必须先看这条</td></tr><tr><td><a href="https://github.com/coder/ghostty-web" target="_blank" rel="noreferrer">ghostty-web</a></td><td>TypeScript · <strong>2806★</strong> · MIT · 建 2025-11 · 最近 push 2026-07</td><td>把 Ghostty 终端编成 WASM，网页里跑全功能终端，兼容 xterm.js API</td><td>中高。网页端演示/教学/远程终端入口；本地 zsh 环境搬进浏览器</td></tr><tr><td><a href="https://github.com/renezander030/capcut-cli" target="_blank" rel="noreferrer">capcut-cli</a></td><td>JS · <strong>500★</strong> · MIT · 活跃 2026-09-14 · 建 2026-04</td><td>剪映/CapCut 非官方 CLI，直接读写工程 <code>draft_content.json</code>，做字幕/时长/变速/长转短</td><td>中。「长视频剪短」的自动化有想象空间，与库内短视频/内容生产相关。<strong>⚠️ 非官方接口、项目仅 5 个月大，工程文件格式随时可能被官方改坏</strong></td></tr><tr><td><a href="https://github.com/mailez-hq/mailez" target="_blank" rel="noreferrer">mailez</a></td><td>Go · <strong>72★</strong> · <strong>AGPL-3.0</strong> · 活跃 2026-09-16 · <strong>建 2026-08-29</strong></td><td>自托管邮件系统：SMTP/IMAP/POP3/CardDAV/CalDAV + Webmail + Docker Compose 一条命令</td><td>中。功能面完整、单二进制很诱人。<strong>⚠️ 三重提醒</strong>：项目仅 3 周龄（生产风险高）＋AGPL＋<strong>自托管邮件真正的难点从来不是软件，是 IP 信誉与送达率</strong>（新 IP 进垃圾箱、Gmail/Outlook 白名单）。想用请先算运维账</td></tr><tr><td><a href="https://github.com/philocalyst/infat" target="_blank" rel="noreferrer">Infat</a></td><td>Rust · <strong>417★</strong> · BlueOak-1.0.0 · 建 2025-03 · <strong>最近 push 2026-04（转凉）</strong></td><td>Mac 上批量设置“某后缀文件用哪个 App 打开”的 CLI</td><td>中。适合整理本地素材/工程文件的默认打开方式，轻量</td></tr><tr><td><a href="https://github.com/xdadda/mini-photo-editor" target="_blank" rel="noreferrer">mini-img-editor</a></td><td>JS · <strong>538★</strong> · MIT · <strong>最近 push 2025-10（停更）</strong></td><td>WebGL 在线图片编辑器，界面极简，偏原型演示</td><td>低。可当“网页版轻量修图”的代码参考</td></tr><tr><td><a href="https://github.com/Yudaotor/lyrimuse" target="_blank" rel="noreferrer">Lyrimuse</a></td><td>Swift · <strong>52★</strong> · GPL-3.0 · 活跃 2026-09-18 · 建 2026-07</td><td>macOS 桌面歌词，逐词同步，支持 Apple Music/Spotify/QQ/网易云/酷狗 + 浏览器</td><td>低（个人体验类）。自认是 LyricsX 的活跃替代品</td></tr><tr><td><a href="https://github.com/lingyired/status-trio" target="_blank" rel="noreferrer">Status Trio</a></td><td>Swift · <strong>290★</strong> · Apache-2.0 · 建 <strong>2026-09-12</strong>（一周内）</td><td>Mac 菜单栏 Wi-Fi/电池/音量三合一图标</td><td>低（尝鲜类，热度高但项目极新）</td></tr><tr><td><a href="https://github.com/EvanZhouDev/polycompiler" target="_blank" rel="noreferrer">Polycompiler</a></td><td>JS · <strong>310★</strong> · <strong>无许可证</strong> · <strong>最近 push 2025-03（停更）</strong></td><td>把 JS 脚本和 Python 脚本合成一个文件，两种解释器都能跑</td><td>低。概念有趣（多语言 polyglot），但<strong>无 LICENSE ＝ 默认保留全部权利，不能合法商用/分发</strong>；且已停更</td></tr></tbody></table><p><strong>小结（工具层的判断）</strong>：本期工具里对用户真正有增量的是 <strong>Great Tables（出表）＋CryptPad（自托管加密文档）</strong>，外加两个“注意坑”的反面样本（mailez 的邮件送达率、Polycompiler 的无许可证）。自托管类项目（CryptPad/mailez）都是 <strong>AGPL-3.0</strong>——这与库内 MiroFish 评估是同一条硬约束，建议在知识库里把“自托管 = 先查许可证”变成一个固定检查项。</p><hr><h2 id="五、资源" tabindex="-1">五、资源 <a class="header-anchor" href="#五、资源" aria-label="Permalink to &quot;五、资源&quot;">​</a></h2><ol><li><strong>gpcb.net</strong> —— 网络设备拓扑图的网页设计工具（画网络架构图，比通用绘图工具更对味）。</li><li><strong>视觉风格图鉴</strong> —— 用同一颗苹果展示 100 多种视觉风格（如霓虹风格）。做内容/封面选风格时的对照参考。</li><li><strong>AI IP 检测</strong>（store.xiu.ai/zh/ai-ip）—— 显示你连 Claude、ChatGPT、Grok、Perplexity、Cloudflare 时的<strong>实际出口 IP</strong>。→ <strong>实用</strong>：用中转/自建代理调 API 时，用来验证流量到底从哪个 IP 出去（排障、合规、风控自查）。</li><li><strong>引力（Gravity）</strong> —— 网页多媒体教程，讲万有引力。</li></ol><hr><h2 id="六、图片" tabindex="-1">六、图片 <a class="header-anchor" href="#六、图片" aria-label="Permalink to &quot;六、图片&quot;">​</a></h2><ol><li><strong>F-35 飞行员头盔</strong> —— 号称世界最贵头盔，<strong>40 万美元/个（约人民币 300 万）</strong>。贵的核心不是材料而是<strong>传感器融合</strong>：连接飞机传感器、接收处理多路数据、内置 360 度显示、提供夜视与飞行数据；每个头盔 3D 扫描定制，由碳纤维、凯夫拉与各种光学元件制成。→ 典型的“算力/信息整合 &gt; 硬件本体”的定价结构，与 AI 时代软件价值迁移同构。</li><li><strong>苏联 Mi-6 直升机</strong> —— 1960 年代设想用直升机运客，Mi-6 是当时世界最大直升机，<strong>可载 80 名乘客</strong>，长约 33 米、高 10 米，每排 5 座、机上有厕所；只为运送东部油气区乘客造过一架。→ 工程史上的“过度设计典型案例”：能力惊人但经济性不成立。</li></ol><hr><h2 id="七、文摘-糊状千层面-slop-lasagna" tabindex="-1">七、文摘：糊状千层面（slop lasagna） <a class="header-anchor" href="#七、文摘-糊状千层面-slop-lasagna" aria-label="Permalink to &quot;七、文摘：糊状千层面（slop lasagna）&quot;">​</a></h2><p><strong>原文要点</strong></p><ul><li>现实里大多数程序员的代码都很糟。但垃圾分等级： <ul><li><strong>意大利面条式代码</strong>（Spaghetti code）：乱成一团，根本理不清。</li><li><strong>糊状千层面</strong>（slop lasagna）：也糊在一起，但<strong>分成了很多层</strong>，至少可以按层拆开。</li></ul></li><li>结论句：即使写不出优秀代码，<strong>也要避免意大利面，争取写千层面</strong>。</li><li>范例是 React：把代码拆成组件，好处是<strong>哪怕每个组件都是垃圾，至少可以单独替换</strong>。删除/复制/内联/重写组件都很容易，因为组件之间是分离的——“某人写了一个 10000 行的垃圾组件，哪有什么关系呢，最终有人会重写它，它影响不到代码库的其他部分。”</li><li><strong>真正重要的三件事</strong>： <ol><li>数据如何在系统中流动（输入从哪来、输出什么、存了什么）；</li><li>用户体验（明显漏洞、糟糕性能、前后不一致）；</li><li>基本抽象概念是否正确、有没有误用。</li></ol></li><li>只要这三点 OK ＋代码是<strong>组件式可抽换结构</strong>，单层写得烂就无关大局。</li></ul><p><strong>我的评注</strong></p><p>这是本期的<strong>方法论亮点</strong>，而且是 AI 时代的必然产物：</p><ul><li>过去“分层”是<strong>为了好读</strong>（人能读懂整块）；现在分层的意义是<strong>为了好换</strong>（哪一层都可能由 AI 重写）。当写代码的成本趋零、<strong>替换</strong>的成本成为主要成本时，架构的评判标准就从“优雅”转成“<strong>可切割性与可替换性</strong>”。</li><li>这解释了一个反直觉现象：为什么 AI 写的代码能撑住生产——不是因为每段代码变好了，而是因为<strong>烂被局部化了</strong>。糊状千层面的关键不是质量，而是<strong>故障/烂代码的传播半径被层边界截断</strong>。</li><li>与库内两条线合流：① <code>gear-shaft-org-reinvention.md</code>（组织的“天轴”＝耦合结构，推倒重来优于外挂）；② 认知萎缩里的 <strong>workslop</strong>（AI 生成的半成品工作）——workslop 之所以致命，常常因为它<strong>穿透了层</strong>（一个 AI 生成的错误抽象被到处引用）。所以 AI 时代的代码规范第一条可以是：<strong><em>让 AI 一次只动一层</em>。</strong></li><li>延伸：Karpathy 式知识库的 <strong>Compiled Truth + Timeline 分层</strong>（<code>llm-wiki-gbrain-knowledge-paradigm.md</code>）本质是同一招——分层不是为了美，是为了让过时/错误的部分能被<strong>整层替换</strong>而不污染全局。</li></ul><hr><h2 id="八、言论" tabindex="-1">八、言论 <a class="header-anchor" href="#八、言论" aria-label="Permalink to &quot;八、言论&quot;">​</a></h2><ol><li><strong>“卫星会消耗行星的自转能量，从而加速行星的毁灭。”</strong>（《金星吞噬了自己的卫星吗》）—— 潮汐相互作用把行星自转角动量转移给卫星轨道，卫星退行、行星自转变慢。物理上成立的一类长期演化。</li><li><strong>“代码就是债务”</strong>：两家几乎一样的软件公司，A 用 100 万行代码、B 用 10 万行——<strong>行数只有别人十分之一的公司会表现更好</strong>，因为更少代码 ＝ 更快理解和修改。→ 与文摘（千层面）互为表里：<strong>行数不是资产而是负债</strong>；与 #412 的“注意力稀缺”同源。</li><li><strong>Liz Fong-Jones</strong>：“大模型会将你从一个编写代码的程序员，转变为一个<strong>管理上下文、剔除无关信息、编写详细提示词</strong>的程序员。”→ <strong>这句直接是本知识库存在理由的外部背书</strong>：外脑做的就是“管理上下文、剔除无关信息”的基础设施。关联 <code>topics/ai-brain/</code>、<code>deepseek-harness-agent-runtime.md</code>。</li><li><strong>《AI 不会崩溃，但会经历一场风暴》</strong>：“一位创始人，如果在 2024 年组建了合适的团队却打造了错误的产品，那么坚持到 2027 年，他的团队就会变成久经沙场的团队，很可能打造出正确的产品。失败带来的经验，就像根系中的养分被储存起来，等待下一个春天的到来。”→ 失败经验的<strong>复利模型</strong>（人/团队作为可积累资产）。关联 <code>entrepreneurship/</code>、<code>investment-methods/</code>。</li><li><strong>Ethan Mollick《AI 就是与魔法师合作》</strong>：“GPS 出错我很快发现；Netflix 推荐不好看我就不看了。但 AI 不同，<strong>它越先进，就越难知道它是否出错，因为我们会用 AI 去完成那些我们自己无法完成、也无法验证的任务</strong>。一旦 AI 出错，我们只能不停召唤更强大的 AI，希望咒语能够奏效。<strong>欢迎来到魔法师时代。</strong>”</li></ol><p><strong>评注（本期最重的一句）</strong>：这条与 #412 的主线严丝合缝，并把它推到终点——#412 说“验证成为新瓶颈”，Mollick 说的是<strong>当验证本身也外包给 AI 时，验证就退化为信仰</strong>：你不再是在核验，而是在<strong>用更强的模型给更弱的模型背书</strong>。工程上的应对只有一条老路：<strong>保留一条不依赖 AI 的验证通道</strong>（可执行测试、形式化证明、物理实测、人工复核抽样）。库内 <code>llm-reasoning-verification-thermodynamic.md</code>（可审计验证 / Theoria）与 <code>echo-gap-memory-reward-inflation.md</code>（自评估奖励膨胀）正是这个问题的两条现有线索。</p><hr><h2 id="九、跨主题关联" tabindex="-1">九、跨主题关联 <a class="header-anchor" href="#九、跨主题关联" aria-label="Permalink to &quot;九、跨主题关联&quot;">​</a></h2><table tabindex="0"><thead><tr><th>本期内容</th><th>库内已有主题/文件</th></tr></thead><tbody><tr><td>Shopify 弃 React Native 回原生（AI 吃掉翻译层）</td><td><code>ai-system-architecture/gear-shaft-org-reinvention.md</code>、<code>weekly-412-analysis.md</code></td></tr><tr><td>「AI 万能翻译器」叙事需打折（成本未消失，只是不再决定性）</td><td><code>ai-system-architecture/cognitive-atrophy-knowledge.md</code>、<code>ai-industry-2026-q3-knowledge.md</code></td></tr><tr><td>地图投影＝有损表征，取舍不可兼得</td><td><code>ai-system-architecture/novel-architecture-topological-field.md</code>、<code>tfm-v1-formalization.md</code>、<code>cross-domain-synthesis-2026-q3.md</code></td></tr><tr><td>认知正义 / 谁的表征被放大</td><td><code>topics/mao-zedong/</code>、<code>topics/philosophy/</code></td></tr><tr><td>伪造指挥官音频导致部队混乱</td><td><code>topics/cybersecurity/pentagi-autonomous-pentest.md</code>、<code>ai-system-architecture/llm-reasoning-verification-thermodynamic.md</code></td></tr><tr><td>固态散热 / 石墨烯贴片</td><td><code>topics/materials/2026-q3-breakthroughs.md</code>、<code>topics/wind-energy/</code></td></tr><tr><td>成都词元券 / 词元贷（Token 准公用事业化）</td><td><code>ai-system-architecture/llm-cache-pricing.md</code>、<code>ai-industry-2026-q3-knowledge.md</code>、<code>topics/energysim/</code></td></tr><tr><td>熵的通俗解释</td><td><code>ai-system-architecture/llm-scaling-limits.md</code>、<code>llm-reasoning-verification-thermodynamic.md</code>、<code>topics/philosophy/physics.md</code></td></tr><tr><td>CryptPad / mailez / 反向代理（自托管栈，AGPL）</td><td><code>weekly-412-analysis.md</code>（自托管工具）、<code>topics/cybersecurity/</code></td></tr><tr><td>模糊千层面 / 代码即债务（分层＝可替换）</td><td><code>ai-system-architecture/llm-wiki-gbrain-knowledge-paradigm.md</code>、<code>cognitive-atrophy-knowledge.md</code>、<code>gear-shaft-org-reinvention.md</code></td></tr><tr><td>Liz Fong-Jones：程序员→上下文管理者</td><td><code>topics/ai-brain/</code>、<code>ai-system-architecture/deepseek-harness-agent-runtime.md</code></td></tr><tr><td>Mollick：AI 越强越难验证 → 魔法师时代</td><td><code>ai-system-architecture/llm-reasoning-verification-thermodynamic.md</code>、<code>echo-gap-memory-reward-inflation.md</code></td></tr><tr><td>Google udm 参数（检索技巧）</td><td><code>topics/ai-brain/knowledge-system-arsenal.md</code></td></tr></tbody></table><hr><h2 id="十、一句话判断" tabindex="-1">十、一句话判断 <a class="header-anchor" href="#十、一句话判断" aria-label="Permalink to &quot;十、一句话判断&quot;">​</a></h2><p><strong>本期主线：AI 先吃掉“翻译层”，于是“共享实现”贬值、“贴近真实”增值；而代价是“验证”越来越外置，直到只剩下信与不信。</strong></p><ul><li>主文一（Shopify 弃 RN 回原生）是<strong>翻译层贬值</strong>：跨端对齐这种纯粹的“重复劳动”正是 LLM 最擅长替代的部分，于是中间件的经济地基被抽走——但注意 Shopify 原文说的是“成本不再是决定性因素”，不是“成本消失”。</li><li>主文二（UN 改用 Equal Earth）是<strong>表征的政治</strong>：没有不失真的投影，只有“选哪种失真”的价值观声明；同一个道理适用于摘要、向量与知识图谱。</li><li>两条言论（代码即债务 / 魔法师时代）是同一枚硬币：<strong>产出变便宜，于是“判断”和“验证”变贵，而当验证也外包，剩下的就只有信仰</strong>。</li><li>对你直接有用的三件：<strong>CryptPad（可自托管、端到端加密的文档，注意 AGPL-3.0）、Great Tables（仿真/周报出表）、AI IP 检测（验证中转 API 的真实出口 IP）</strong>。另有两个“坑样本”值得入库当检查项：mailez（自托管邮件的难点是送达率不是软件）、Polycompiler（无 LICENSE ＝ 不可合法分发）。</li></ul><hr><p>关键词：阮一峰, 科技爱好者周刊, React Native, Shopify, Spotify, 原生开发, Swift, Kotlin, 中间层, 翻译层, 编码代理, coding agent, 跨平台框架, 世界地图, 墨卡托投影, 相等地球投影, Equal Earth, Gall-Peters, 联合国决议, 面积失真, 格陵兰, 表征失真, 认知正义, 隐藏摄像头, 凸透镜反射, 合成媒体, 伪造音频, 认知战, 固态散热, 石墨烯, 无风扇笔记本, 词元券, 词元贷, Token 补贴, 成都, 熵, 代码即债务, 糊状千层面, slop lasagna, 分层可替换, 上下文工程, 魔法师时代, Ethan Mollick, 可审计验证, CryptPad, Great Tables, mailez, ghostty-web, capcut-cli, Polycompiler, AGPL, 自托管</p><p>关联：weekly-412-analysis.md、weekly-402-analysis.md、gear-shaft-org-reinvention.md、cognitive-atrophy-knowledge.md、llm-reasoning-verification-thermodynamic.md、echo-gap-memory-reward-inflation.md、llm-scaling-limits.md、llm-cache-pricing.md、llm-wiki-gbrain-knowledge-paradigm.md、ai-industry-2026-q3-knowledge.md、deepseek-harness-agent-runtime.md、novel-architecture-topological-field.md、tfm-v1-formalization.md、topics/materials/2026-q3-breakthroughs.md、topics/cybersecurity/pentagi-autonomous-pentest.md、topics/ai-brain/knowledge-system-arsenal.md、topics/wind-energy/、topics/energysim/、topics/philosophy/physics.md、cross-domain-synthesis-2026-q3.md</p>',74)])])}const p=o(s,[["render",i]]);export{m as __pageData,p as default};
